    '.rcl__wood{position:absolute;inset:0;width:100%;height:100%;display:block;}',
    '.rcl__corner{position:absolute;width:clamp(220px,32vw,520px);height:auto;overflow:visible;}',
    '.rcl__corner--tl{top:0;left:0}.rcl__corner--tr{top:0;right:0}.rcl__corner--bl{bottom:0;left:0}.rcl__corner--br{bottom:0;right:0}',
